gcode_macros.gcode:
[homing_override]
axes: xyz
set_position_z: 0
gcode:
    # ══════════════════════════════════════════════════
    # YUMI Bambu-Grade 2-Phase Sensorless Homing
    # X/Y : YUMI_SENSORLESS_HOME (module yumi_sensorless_homing) — courants,
    #       vitesses et validation multi-tap dans [yumi_sensorless_homing]
    # Z   : nozzle tap via probe_pressure (YUMI_Z_TAP, [yumi_z_tap])
    # Aucune valeur machine ici : tout vient de printer.configfile.settings
    # ══════════════════════════════════════════════════
    {% set retract_coarse = 8 %}
    {% set coarse_travel = 3000 %}
    {% set homing_travel_speed = 1800 %}

    # ── Read stepper limits ──
    {% set x_max = printer.configfile.settings.stepper_x.position_max|float %}
    {% set y_min = printer.configfile.settings.stepper_y.position_min|float %}
    {% set z_max = printer.configfile.settings.stepper_z.position_max|float %}

    {% set raw = params|join('') %}
    {% set has_x = 'X' in raw %}
    {% set has_y = 'Y' in raw %}
    {% set has_z = 'Z' in raw %}
    {% set home_all = not has_x and not has_y and not has_z %}

    G90
    SET_KINEMATIC_POSITION Z=0
    G1 Z20 F300

    # ── Phase 0: Simultaneous XY retract (Bambu-style) ──
    # Clear endstops if carriage is already at a limit
    SET_KINEMATIC_POSITION X={x_max} Y={y_min}
    G1 X{x_max - retract_coarse} Y{y_min + retract_coarse} F{coarse_travel}

    # ── Sensorless prep: neutralise CoolStep/autotune → fenetre StallGuard pleine-gamme ──
    SET_TMC_FIELD STEPPER=stepper_x FIELD=tcoolthrs VALUE=0
    SET_TMC_FIELD STEPPER=stepper_y FIELD=tcoolthrs VALUE=0

    # ── HOME X / Y: multi-tap valide (yumi_sensorless_homing) ──
    # G28 Z seul : X et Y sont homes d'abord (le tap Z demande une position XY vraie)
    {% if home_all or has_x or has_z %}
        YUMI_SENSORLESS_HOME AXIS=X
    {% endif %}
    {% if home_all or has_y or has_z %}
        YUMI_SENSORLESS_HOME AXIS=Y
    {% endif %}

    # ── HOME Z: nozzle tap via probe_pressure ──
    {% if home_all or has_z %}
        SET_KINEMATIC_POSITION Z={z_max}
        YUMI_Z_TAP SAVE=0
        G1 X{x_max} F{homing_travel_speed}
    {% endif %}

    # ── Restore autotune (tuning silencieux coolstep/pwm) ──
    AUTOTUNE_TMC STEPPER=stepper_x
    AUTOTUNE_TMC STEPPER=stepper_y

[delayed_gcode welcome]
initial_duration: 1
gcode:
    _YUMI_MACHINE
    _YUMI_WELCOME

[gcode_macro _YUMI_WELCOME]
description: Startup report — machine class from _YUMI_MACHINE, options read from the config
gcode:
    {% set model = printer["gcode_macro _YUMI_MACHINE"].model %}
    {% set bed_size = printer["gcode_macro _YUMI_MACHINE"].bed_size|int %}
    {% set has_smartbox = 'mcu smartbox' in printer %}
    {% set ns = namespace(yms=0) %}
    {% if 'extruder_stepper extruder0' in printer.configfile.settings %}{% set ns.yms = ns.yms + 1 %}{% endif %}
    {% if 'extruder_stepper extruder1' in printer.configfile.settings %}{% set ns.yms = ns.yms + 1 %}{% endif %}
    {% if 'extruder_stepper extruder2' in printer.configfile.settings %}{% set ns.yms = ns.yms + 1 %}{% endif %}
    {% if 'extruder_stepper extruder3' in printer.configfile.settings %}{% set ns.yms = ns.yms + 1 %}{% endif %}
    {% if 'extruder_stepper extruder4' in printer.configfile.settings %}{% set ns.yms = ns.yms + 1 %}{% endif %}
    {% if 'extruder_stepper extruder5' in printer.configfile.settings %}{% set ns.yms = ns.yms + 1 %}{% endif %}
    {% if 'extruder_stepper extruder6' in printer.configfile.settings %}{% set ns.yms = ns.yms + 1 %}{% endif %}
    {% set ns2 = namespace(dryer_pos="none", has_dryer=false) %}
    {% if 'heater_generic yms-3-pro' in printer.configfile.settings %}{% set ns2.has_dryer = true %}{% set ns2.dryer_pos = "YMS-3" %}{% endif %}
    {% set yms_type = "PRO" if ns2.has_dryer else ("LITE" if ns.yms > 0 else "NONE") %}
    {% set has_probe_pressure = 'probe_pressure' in printer.configfile.settings %}
    {% set probe_type = "pressure" if has_probe_pressure else "standard" %}
    {% set has_adxl = 'mcu rpi' in printer %}
    {% if ns.yms > 0 %}
        {% set full_model = model ~ " " ~ ns.yms ~ "YMS-" ~ yms_type %}
    {% else %}
        {% set full_model = model ~ " 1COLOR" %}
    {% endif %}
    SAVE_VARIABLE VARIABLE=machine_model VALUE="'{model}'"
    SAVE_VARIABLE VARIABLE=machine_full_model VALUE="'{full_model}'"
    SAVE_VARIABLE VARIABLE=machine_bed_size VALUE={bed_size}
    SAVE_VARIABLE VARIABLE=machine_yms_count VALUE={ns.yms}
    SAVE_VARIABLE VARIABLE=machine_yms_type VALUE="'{yms_type}'"
    SAVE_VARIABLE VARIABLE=machine_has_smartbox VALUE={1 if has_smartbox else 0}
    SAVE_VARIABLE VARIABLE=machine_probe_type VALUE="'{probe_type}'"
    SAVE_VARIABLE VARIABLE=machine_has_adxl VALUE={1 if has_adxl else 0}
    # a fresh machine has no mesh yet: loading a missing profile is an error popup at every boot
    {% if "default" in printer.bed_mesh.profiles %}
        BED_MESH_PROFILE LOAD=default
    {% endif %}
    RESPOND MSG="YUMI {full_model} | Probe:{probe_type} | ADXL:{'yes' if has_adxl else 'no'} | Smartbox:{'yes' if has_smartbox else 'no'}"
    M117 {full_model}

[gcode_macro SET_GCODE_OFFSET]
rename_existing: _SET_GCODE_OFFSET
gcode:
    {% if printer.save_variables.variables.gcode_offsets %}
        {% set offsets = printer.save_variables.variables.gcode_offsets %}
    {% else %}
        {% set offsets = {'x': None,'y': None,'z': None} %}
    {% endif %}
    {% set ns = namespace(offsets={'x': offsets.x,'y': offsets.y,'z': offsets.z}) %}
    _SET_GCODE_OFFSET {% for p in params %}{'%s=%s '% (p, params[p])}{% endfor %}
    {%if 'X' in params %}{% set null = ns.offsets.update({'x': params.X}) %}{% endif %}
    {%if 'Y' in params %}{% set null = ns.offsets.update({'y': params.Y}) %}{% endif %}
    {%if 'Z' in params %}{% set null = ns.offsets.update({'z': params.Z}) %}{% endif %}
    {%if 'Z_ADJUST' in params %}
        {%if ns.offsets.z == None %}{% set null = ns.offsets.update({'z': 0}) %}{% endif %}
        {% set null = ns.offsets.update({'z': (ns.offsets.z | float) + (params.Z_ADJUST | float)}) %}
    {% endif %}
    SAVE_VARIABLE VARIABLE=gcode_offsets VALUE="{ns.offsets}"

[gcode_macro PAUSE]
description: Pause the running print
rename_existing: PAUSE_BASE
variable_extrude: 5.0
gcode:
    SAVE_VARIABLE VARIABLE=fan_speed VALUE={printer.fan.speed * 255}
    {% set act_x = printer.toolhead.position.x|float %}
    {% set act_y = printer.toolhead.position.y|float %}
    {% set act_z = printer.toolhead.position.z|float %}
    SAVE_VARIABLE VARIABLE=pause_x VALUE={act_x}
    SAVE_VARIABLE VARIABLE=pause_y VALUE={act_y}
    SAVE_VARIABLE VARIABLE=pause_z VALUE={act_z}
    M106 S0
    {% set E = printer["gcode_macro PAUSE"].extrude|float %}
    {% set x_park = printer.toolhead.axis_maximum.x|float %}
    {% set y_park = printer.toolhead.axis_maximum.y|float / 2 %}
    {% set max_z = printer.toolhead.axis_maximum.z|float %}
    {% set act_z = printer.toolhead.position.z|float %}
    {% if act_z < (max_z - 2.0) %}
        {% set z_safe = 2.0 %}
    {% else %}
        {% set z_safe = max_z - act_z %}
    {% endif %}
    PAUSE_BASE
    G91
    {% if printer.extruder.can_extrude|lower == 'true' %}
        G1 E-{E} F2100
    {% else %}
        {action_respond_info("Extruder not hot enough")}
    {% endif %}
    {% if "xyz" in printer.toolhead.homed_axes %}
        G1 Z{z_safe} F900
        G90
        G1 X{x_park} Y{y_park} F6000
    {% else %}
        {action_respond_info("Printer not homed")}
    {% endif %}
    M117 pause print

[gcode_macro RESUME]
description: Resume the running print
rename_existing: RESUME_BASE
variable_prime: 40.0
gcode:
    {% set svv = printer.save_variables.variables %}
    {% set fan_speed = svv.fan_speed|default(0)|int %}
    {% set x_park = printer.toolhead.axis_maximum.x|float %}
    G1 X{x_park} F6000
    {% if 'pause_x' in svv and 'pause_y' in svv and 'pause_z' in svv %}
        {% set px = svv.pause_x|float %}
        {% set py = svv.pause_y|float %}
        {% set pz = svv.pause_z|float %}
    {% else %}
        {action_respond_info("Pause coordinates not found")}
        M117 ERROR: Unknown pause position
    {% endif %}
    {% set E = printer["gcode_macro PAUSE"].extrude|float %}
    {% if 'VELOCITY' in params|upper %}
        {% set get_params = ('VELOCITY=' + params.VELOCITY) %}
    {% else %}
        {% set get_params = "" %}
    {% endif %}
    {% if printer.extruder.can_extrude|lower == 'true' %}
        G91
        G1 E{prime|float} F300
        G92 E0
        M106 S255
        G4 P5000
        G90
        G1 X{x_park - 11} F26000
        G92 E0
        G1 X{px} Y{py} Z{pz} F6000
        G1 E{E} F10800
        M106 S{fan_speed}
    {% else %}
        {action_respond_info("Extruder not hot enough")}
    {% endif %}
    RESUME_BASE {get_params}
    M117 printing...

[gcode_macro _YUMI_TIP]
description: Single source of the filament tip-shaping unload sequence (mm and mm/s); tune live with SET_GCODE_VARIABLE, then freeze the winning values here
# 1. short fast retract that breaks the pressure — the only step done over the part (CANCEL_PRINT)
variable_first_len: 7
variable_first_speed: 80
# 2. the cut: fast pull that shears the molten part from the solid filament
variable_cut_len: 10
variable_cut_speed: 65
# 3. slow pull: the tip stretches and cools as it leaves the melt zone
variable_slow_len: 20
variable_slow_speed: 5
# 4. the pull up into the PTFE (tip visible above the hotend from ~142 mm total)
variable_pull_len: 110
variable_pull_speed: 35
# reload: back down the same distance, then a small slow purge
variable_purge_len: 10
variable_purge_speed: 5
gcode:
    {% set t = printer["gcode_macro _YUMI_TIP"] %}
    RESPOND MSG="tip: first {t.first_len}mm@{t.first_speed} | cut {t.cut_len}mm@{t.cut_speed} | slow {t.slow_len}mm@{t.slow_speed} | pull {t.pull_len}mm@{t.pull_speed} | purge {t.purge_len}mm@{t.purge_speed} (mm/s)"

[gcode_macro YUMI_UNLOAD_TIP]
description: Tip-shaping unload: first retract, cut, slow pull, pull up into the PTFE. SKIP_FIRST=1 when the first retract was already done. Any _YUMI_TIP variable can be given as a parameter (CUT_SPEED=65 ...).
gcode:
    {% set t = printer["gcode_macro _YUMI_TIP"] %}
    {% set first_len = params.FIRST_LEN|default(t.first_len)|float %}
    {% set first_speed = params.FIRST_SPEED|default(t.first_speed)|float %}
    {% set cut_len = params.CUT_LEN|default(t.cut_len)|float %}
    {% set cut_speed = params.CUT_SPEED|default(t.cut_speed)|float %}
    {% set slow_len = params.SLOW_LEN|default(t.slow_len)|float %}
    {% set slow_speed = params.SLOW_SPEED|default(t.slow_speed)|float %}
    {% set pull_len = params.PULL_LEN|default(t.pull_len)|float %}
    {% set pull_speed = params.PULL_SPEED|default(t.pull_speed)|float %}
    SAVE_GCODE_STATE NAME=yumi_tip
    M83
    {% if params.SKIP_FIRST|default(0)|int == 0 %}
        G1 E-{first_len} F{(first_speed * 60)|int}
    {% endif %}
    G1 E-{cut_len} F{(cut_speed * 60)|int}
    G1 E-{slow_len} F{(slow_speed * 60)|int}
    G1 E-{pull_len} F{(pull_speed * 60)|int}
    RESTORE_GCODE_STATE NAME=yumi_tip
    # the head sensor must have released: pulls more if needed, error if the filament never left
    YUMI_UNLOAD_CHECK

[gcode_macro YUMI_TIP_TEST]
description: Filament change without the cutter: CYCLES x (load + purge, tip-shaping unload up into the PTFE, wait WAIT s), then a final load. TEMP hotend, TOOL selects the YMS feeder (T<n>) on a ChromaX12. The head does not move (parked at the pop tool if homed). Tip parameters as in YUMI_UNLOAD_TIP.
gcode:
    {% set t = printer["gcode_macro _YUMI_TIP"] %}
    {% set cycles = params.CYCLES|default(2)|int %}
    {% set temp = params.TEMP|default(220)|float %}
    {% set wait = params.WAIT|default(10)|float %}
    {% set bed_size = printer["gcode_macro _YUMI_MACHINE"].bed_size|float %}
    {% set first_len = params.FIRST_LEN|default(t.first_len)|float %}
    {% set cut_len = params.CUT_LEN|default(t.cut_len)|float %}
    {% set slow_len = params.SLOW_LEN|default(t.slow_len)|float %}
    {% set pull_len = params.PULL_LEN|default(t.pull_len)|float %}
    {% set pull_speed = params.PULL_SPEED|default(t.pull_speed)|float %}
    {% set purge_len = params.PURGE_LEN|default(t.purge_len)|float %}
    {% set purge_speed = params.PURGE_SPEED|default(t.purge_speed)|float %}
    {% set load_len = first_len + cut_len + slow_len + pull_len %}
    {% set tip_args = [] %}
    {% for k, v in params.items() if k not in ('CYCLES', 'TEMP', 'WAIT', 'TOOL') %}{% set _ = tip_args.append(k ~ '=' ~ v) %}{% endfor %}
    {% if params.TOOL is defined %}
        T{params.TOOL|int}
    {% endif %}
    {% if "xyz" in printer.toolhead.homed_axes %}
        SAVE_GCODE_STATE NAME=yumi_tip_test
        G90
        {% if printer.toolhead.position.z < 20 %}
            G1 Z20 F600
        {% endif %}
        G1 X{bed_size + 7} F12000
        G1 X{bed_size + 20} F5000
        RESTORE_GCODE_STATE NAME=yumi_tip_test
    {% endif %}
    RESPOND MSG="tip test: {cycles} cycle(s), {temp}C, load to the head sensor + purge {purge_len}mm, wait {wait}s"
    M109 S{temp}
    SAVE_GCODE_STATE NAME=yumi_tip_test2
    M83
    {% for i in range(cycles) %}
        RESPOND MSG="tip test {i + 1}/{cycles}: load to the head sensor"
        YUMI_LOAD_TO_HEAD
        G1 E{purge_len} F{(purge_speed * 60)|int}
        M400
        RESPOND MSG="tip test {i + 1}/{cycles}: unload (tip shaping)"
        YUMI_UNLOAD_TIP {tip_args|join(' ')}
        M400
        RESPOND MSG="tip test {i + 1}/{cycles}: tip up in the PTFE, waiting {wait}s"
        G4 P{(wait * 1000)|int}
    {% endfor %}
    RESPOND MSG="tip test: final load to the head sensor + purge — check the filament came back to the nozzle"
    YUMI_LOAD_TO_HEAD
    G1 E{purge_len} F{(purge_speed * 60)|int}
    M400
    RESTORE_GCODE_STATE NAME=yumi_tip_test2
    RESPOND MSG="tip test done"

[gcode_macro PRINT_START]
description: First line of the slicer start g-code. BED_X/BED_Y/MODEL/HEAD/HOTEND/NOZZLE come from the slicer profile: a file sliced for another machine, head, hotend or nozzle is cancelled here, cold, before any heating or motion.
gcode:
    {% set machine = printer["gcode_macro _YUMI_MACHINE"] %}
    {% set product = printer["gcode_macro _YUMI_PRODUCT"] %}
    {% set bed = machine.bed_size|float %}
    {% set model = params.MODEL|default("")|string %}
    {% set ns = namespace(reason="", checked=false) %}
    # bed size -> machine model (X axis length)
    {% if params.BED_X is defined %}
        {% set ns.checked = true %}
        {% set bed_x = params.BED_X|float %}
        {% set bed_y = params.BED_Y|default(params.BED_X)|float %}
        {% if bed <= 0 %}
            RESPOND TYPE=echo MSG="PRINT_START: machine size unknown (_YUMI_MACHINE), slicer profile not checked"
        {% elif (bed_x - bed)|abs > 1 or (bed_y - bed)|abs > 1 %}
            {% set what = model if model else (bed_x|int ~ "x" ~ bed_y|int ~ " bed") %}
            {% set ns.reason = "File sliced for " ~ what ~ ". Please re-slice with the " ~ machine.model ~ " profile." %}
        {% endif %}
    {% endif %}
    # print head (Direct Drive / ChromaX12): what this printer.cfg was generated for
    {% set head = params.HEAD|default("")|string %}
    {% if not ns.reason and head and product.head %}
        {% set ns.checked = true %}
        {% if head|lower|replace(" ", "") != product.head|lower|replace(" ", "") %}
            {% set ns.reason = "File sliced for " ~ head ~ " head. This machine is set as " ~ product.head ~ ". Re-slice, or change the head in Printer Config." %}
        {% endif %}
    {% endif %}
    # hotend type (Low waste / High Flow); empty = single hotend machine, not applicable
    {% set hotend = params.HOTEND|default("")|string %}
    {% if not ns.reason and hotend and product.hotend %}
        {% set ns.checked = true %}
        {% if hotend|lower|replace(" ", "") != product.hotend|lower|replace(" ", "") %}
            {% set ns.reason = "File sliced for " ~ hotend ~ " hotend. This machine is set as " ~ product.hotend ~ ". Re-slice, or change the hotend in Printer Config." %}
        {% endif %}
    {% endif %}
    # nozzle: the diameter of [extruder] is authoritative
    {% if not ns.reason and params.NOZZLE is defined %}
        {% set ns.checked = true %}
        {% set nozzle = printer.configfile.settings.extruder.nozzle_diameter|float %}
        {% if (params.NOZZLE|float - nozzle)|abs > 0.01 %}
            {% set ns.reason = "File sliced for " ~ params.NOZZLE ~ " nozzle. This machine is set as " ~ nozzle ~ ". Re-slice, or change the nozzle in Printer Config." %}
        {% endif %}
    {% endif %}
    {% if ns.reason %}
        # short message, no "Error evaluating ..." wrapper: cancel the SD print cleanly
        # (CANCEL_PRINT_DEFAULT = Klipper's own cancel, renamed by the CANCEL_PRINT macro
        # of this trunk: no motion, nothing has heated yet)
        RESPOND TYPE=error MSG="{ns.reason}"
        M117 Wrong slicer profile
        CANCEL_PRINT_DEFAULT
    {% elif not ns.checked %}
        RESPOND TYPE=echo MSG="PRINT_START: the file carries no profile data (old start g-code), slicer profile not checked"
    {% endif %}
    {% if not ns.reason %}
        # machine state: the T macros and the YMS insert_gcode take their printing branch,
        # PRINT_END / CANCEL_PRINT / _YUMI_PRINT_ERROR put it back
        SAVE_VARIABLE VARIABLE=printing_start VALUE=True
        # power-loss recovery (Yumi_PLR, plr.cfg): clear the previous record, remember this file
        SAVE_VARIABLE VARIABLE=was_interrupted VALUE=True
        {% if "gcode_shell_command clear_plr" in printer.configfile.settings %}
            RUN_SHELL_COMMAND CMD=clear_plr
        {% endif %}
        {% if "gcode_macro save_last_file" in printer %}
            save_last_file
        {% endif %}
    {% endif %}
    # the motherboard fan is a controller_fan: automatic whenever motors or heaters are active
    G92 E0

[gcode_macro PRINT_END]
description: The slicer end g-code is exactly this line. Off the part, pop tool, tip-shaping unload until the head switch releases (nozzle still hot), then heaters and fans off, state and PLR cleared, motors off. The filament never stays in the head between two prints
gcode:
    M400
    _YUMI_LEAVE_PART_AND_UNLOAD
    M220 S100
    M221 S100
    ALL_FAN_OFF
    TURN_OFF_HEATERS
    SAVE_VARIABLE VARIABLE=was_interrupted VALUE=False
    SAVE_VARIABLE VARIABLE=printing_start VALUE=False
    # power-loss recovery (Yumi_PLR, plr.cfg) has nothing to resume any more
    {% if "gcode_macro clear_last_file" in printer %}
        clear_last_file
    {% endif %}
    {% if "gcode_shell_command clear_plr" in printer.configfile.settings %}
        RUN_SHELL_COMMAND CMD=clear_plr
    {% endif %}
    M84
    # every refresh_every prints: propose the reference scan + mesh on the screen, never by itself
    _YUMI_MESH_REFRESH_PROMPT

[gcode_macro ALL_FAN_OFF]
description: Turn off all fans
gcode:
    M107
    SET_FAN_SPEED FAN=Aux_Fan SPEED=0

[gcode_macro M600]
description: Filament change (pause)
gcode:
    PAUSE

[gcode_macro M84]
description: Disable motors with position reset
rename_existing: M84.1
gcode:
    SET_STEPPER_ENABLE STEPPER=stepper_x enable=0
    SET_STEPPER_ENABLE STEPPER=stepper_y enable=0
    SET_STEPPER_ENABLE STEPPER=stepper_z enable=0
    SET_STEPPER_ENABLE STEPPER=extruder enable=0
    SET_KINEMATIC_POSITION

[gcode_macro UNLOAD_FILAMENT]
description: Unload filament with auto-heat
gcode:
    {% if printer.idle_timeout.state == "Printing" %}
        {action_respond_info("Can't unload while printing!")}
    {% else %}
        {% if printer.extruder.temperature < 200 %}
            M109 S{params.TEMP|default(220)}
        {% endif %}
        G90
        G1 X0 F5000
        G1 X-12 F2000
        G92 E0
        G1 E-30 F800
        G1 X20 F5000
        RESPOND MSG="Filament unloaded"
    {% endif %}

[gcode_macro LOAD_FILAMENT]
description: Load filament with auto-heat
gcode:
    {% if printer.idle_timeout.state == "Printing" %}
        {action_respond_info("Can't load while printing!")}
    {% else %}
        {% if printer.extruder.temperature < 200 %}
            M109 S{params.TEMP|default(220)}
        {% endif %}
        G91
        G1 E50 F800
        G1 E30 F150
        G90
        RESPOND MSG="Filament loaded"
    {% endif %}

[gcode_macro PID_CALIBRATION]
description: PID calibration — PID_CALIBRATION / PID_CALIBRATION BED=70 HOTEND=250
gcode:
    {% if printer.idle_timeout.state == "Printing" %}
        {action_respond_info("Can't run this macro right now!")}
    {% else %}
        {% set bed_temp = params.BED|default(65)|int %}
        {% set hotend_temp = params.HOTEND|default(220)|int %}
        {% set do_save = true if params.SAVE is not defined or params.SAVE|upper != "NO" else false %}
        {action_respond_info("PID Calibration — Bed:%dC Hotend:%dC Save:%s" % (bed_temp, hotend_temp, "yes" if do_save else "no"))}
        BED_DETECTION
        G1 Z50 F1500
        M400
        {action_respond_info("Phase 1/2 — Bed PID at %dC..." % bed_temp)}
        PID_CALIBRATE HEATER=heater_bed TARGET={bed_temp}
        M400
        {action_respond_info("Phase 2/2 — Hotend PID at %dC..." % hotend_temp)}
        M106
        PID_CALIBRATE HEATER=extruder TARGET={hotend_temp}
        M107
        M400
        TURN_OFF_HEATERS
        {% if do_save %}
            {action_respond_info("PID Calibration done — saving...")}
            SAVE_CONFIG
        {% else %}
            {action_respond_info("PID Calibration done — NOT saved (SAVE=NO).")}
        {% endif %}
    {% endif %}

[gcode_macro ADXL_AXE_X]
description: X axis resonance calibration
gcode:
    {% if printer.idle_timeout.state == "Printing" %}
        {action_respond_info("Can't run this macro right now!")}
    {% else %}
        {% if printer.toolhead.homed_axes != "xyz" %}
            G28
        {% endif %}
        M400
        SHAPER_CALIBRATE AXIS=X
    {% endif %}

[gcode_macro ADXL_AXE_Y]
description: Y axis resonance calibration
gcode:
    {% if printer.idle_timeout.state == "Printing" %}
        {action_respond_info("Can't run this macro right now!")}
    {% else %}
        {% if printer.toolhead.homed_axes != "xyz" %}
            G28
        {% endif %}
        M400
