[gcode_macro SAVECONFIG]
gcode:
    SAVE_CONFIG

[gcode_macro M106]
rename_existing: M106.1
gcode:
    {% set S = params.S|default(255)|int %}
    {% if params.P is defined %}
        {% set P = params.P|int %}
        {% if P == 2 %}
            SET_FAN_SPEED FAN=Aux_Fan SPEED={S / 255.0}
        {% elif P == 3 %}
            # P3 = motherboard fan: a controller_fan, automatic (motors/heaters active) — nothing to set
        {% else %}
            M106.1 S{S}
        {% endif %}
    {% else %}
        M106.1 S{S}
    {% endif %}

[gcode_macro M107]
rename_existing: M107.1
gcode:
    {% if params.P is defined %}
        {% set P = params.P|int %}
        {% if P == 2 %}
            SET_FAN_SPEED FAN=Aux_Fan SPEED=0
        {% elif P == 3 %}
            # P3 = motherboard fan: a controller_fan, automatic — nothing to set
        {% else %}
            M107.1
        {% endif %}
    {% else %}
        M107.1
    {% endif %}

[gcode_macro M201]
description: Sets maximum acceleration.
gcode:
    {% if 'X' in params or 'Y' in params %}
        {% set accel = (params.X|default(params.Y)|float, params.Y|default(params.X)|float)|min %}
        SET_VELOCITY_LIMIT ACCEL={accel} ACCEL_TO_DECEL={accel * 0.5}
    {% else %}
        SET_VELOCITY_LIMIT
    {% endif %}

[gcode_macro M203]
description: Sets maximum velocity.
gcode:
    {% if 'X' in params or 'Y' in params %}
        {% set velocity = (params.X|default(params.Y)|float, params.Y|default(params.X)|float)|min %}
        SET_VELOCITY_LIMIT VELOCITY="{velocity}"
    {% else %}
        SET_VELOCITY_LIMIT
    {% endif %}

[gcode_macro M205]
description: Sets square corner velocity.
gcode:
    {% if 'X' in params or 'Y' in params %}
        SET_VELOCITY_LIMIT SQUARE_CORNER_VELOCITY="{(params.X|default(0)|float, params.Y|default(0)|float)|min}"
    {% else %}
        SET_VELOCITY_LIMIT
    {% endif %}

[gcode_macro M900]
description: Set Pressure Advance.
gcode:
    {% if 'K' in params %}
        SET_PRESSURE_ADVANCE ADVANCE={params.K}
    {% endif %}

[gcode_macro Z_TAP]
description: Set Z=0 via nozzle tap (probe pressure). Auto-detects printing state.
gcode:
    {% set SAVE_PARAM = params.SAVE|default(0)|int %}
    {% set is_printing = printer.idle_timeout.state == "Printing" %}
    {% if is_printing %}
        M109 S150
        WIPE_NOZZLE
        YUMI_Z_TAP SAVE={SAVE_PARAM}
        M104 S0
    {% else %}
        {% if printer.toolhead.homed_axes != "xyz" %}
            G28
        {% endif %}
        {% set z_max = printer.configfile.settings.stepper_z.position_max|float %}
        SET_KINEMATIC_POSITION Z={z_max}
        YUMI_Z_TAP SAVE={SAVE_PARAM}
    {% endif %}

[gcode_macro BED_DETECTION]
description: Bed presence + Z frame on the metal reference plate. Never scanned yet -> BED_SCAN_ZERO first (synchronous), then probes the saved point.
gcode:
    {% set sv = printer.save_variables.variables %}
    {% if 'bed_detect_x' not in sv or 'bed_detect_y' not in sv %}
        RESPOND MSG="BED_DETECTION: metal reference not calibrated yet -> BED_SCAN_ZERO"
        BED_SCAN_ZERO
    {% endif %}
    # rendered AFTER the scan: reads the freshly saved reference
    _BED_DETECT_AT_REF

[gcode_macro _BED_DETECT_AT_REF]
description: Phase 1 metal plate (saved point) -> Z=0 ; phase 2 right end of the plate -> bed present
gcode:
    {% set sv = printer.save_variables.variables %}
    {% set mx = sv.bed_detect_x|float %}
    {% set my = sv.bed_detect_y|float %}
    {% set x_max = printer.configfile.settings.stepper_x.position_max|float %}
    {% set z_max = printer.configfile.settings.stepper_z.position_max|float %}
    {% set bed_probe_x_inset = 14 %}
    {% if 'xy' not in printer.toolhead.homed_axes %}
        G28 X
        G28 Y
    {% endif %}
    # fake high Z so the probe can descend, lift first (never "triggered prior to movement")
    SET_KINEMATIC_POSITION Z={z_max - 20}
    G90
    G1 Z{z_max - 12} F600
    G1 X{mx} Y{my} F12000
    PROBE
    SET_KINEMATIC_POSITION Z=0
    G1 Z10 F500
    G1 X{x_max - bed_probe_x_inset} Y{my} F12000
    PROBE
    SET_KINEMATIC_POSITION Z=0
    G1 Z10 F500
    G1 X{x_max} F9000

[gcode_macro PROBE_CALIBRATE]
rename_existing: BASE_PROBE_CALIBRATE
gcode:
    {% set mesh_min = printer.configfile.settings.bed_mesh.mesh_min %}
    {% set mesh_max = printer.configfile.settings.bed_mesh.mesh_max %}
    {% set bed_cx = (mesh_min[0]|float + mesh_max[0]|float) / 2 %}
    {% set bed_cy = (mesh_min[1]|float + mesh_max[1]|float) / 2 %}
    BED_DETECTION
    G1 X{bed_cx} Y{bed_cy} F12000
    BASE_PROBE_CALIBRATE

[gcode_macro SCREWS_TILT_CALCULATE]
rename_existing: BASE_SCREWS_TILT_CALCULATE
gcode:
    {% set x_max = printer.configfile.settings.stepper_x.position_max|float %}
    {% set bed_size = printer["gcode_macro _YUMI_MACHINE"].bed_size|float %}
    {% set y_park = printer.configfile.settings.stepper_y.position_max|float %}
    M140 S50
    BED_DETECTION
    BASE_SCREWS_TILT_CALCULATE
    G1 Z20 F500
    G1 X{bed_size / 2} Y{y_park - 2} F6000
    M140 S0

[gcode_macro BED_MESH_CALIBRATE]
rename_existing: BASE_BED_MESH_CALIBRATE
description: Bed mesh with bed detection; persisted in printer.cfg without restarting Klipper (safe inside a start g-code)
gcode:
    {% set profile_name = params.PROFILE|default('default')|string %}
    # inside a print the bed is already at the print temperature: keep it, no soak;
    # standalone: heat to 65, soak, and switch the bed off afterwards
    {% set bed_target = printer.heater_bed.target|float %}
    {% set standalone = bed_target <= 0 %}
    BED_DETECTION
    G1 Z100
    M190 S{65 if standalone else bed_target}
    {% if standalone %}
        G4 P60000
    {% endif %}
    BASE_BED_MESH_CALIBRATE PROFILE={profile_name}
    BASE_BED_MESH_PROFILE SAVE={profile_name}
    # scripts/save_mesh.py rewrites the #*# [bed_mesh] block like SAVE_CONFIG would, without the restart
    RUN_SHELL_COMMAND CMD=save_mesh
    # a fresh mesh: the print counter of BED_MESH_PROFILE's periodic refresh starts again
    SAVE_VARIABLE VARIABLE=prints_since_mesh VALUE=0
    {% if standalone %}
        M140 S0
    {% endif %}

[gcode_macro BED_DETECT_SYNC]
description: Kept for existing start g-codes: same as BED_DETECTION (synchronous, scans the reference first if needed)
gcode:
    BED_DETECTION

[gcode_macro WIPE_NOZZLE]
description: Wipe nozzle on brush
gcode:
        {% if printer.extruder.temperature < 125 %}
            M109 S130
        {% endif %}
        {% set bed_size = printer["gcode_macro _YUMI_MACHINE"].bed_size|float %}
        {% set brush_x_min = bed_size / 2 + 18.5 %}
        {% set brush_x_max = bed_size / 2 + 45.5 %}
        {% set brush_y_min = bed_size + 6 %}
        {% set brush_y_max = bed_size + 11 %}
        {% set brush_z = 2.5 %}
        {% set wipe_passes = 4 %}
        {% set wipe_speed = 6000 %}
        {% if printer.toolhead.homed_axes != "xyz" %}
            G28
        {% endif %}
        G90
        G1 Z10 F300
        G1 X{brush_x_min} Y{brush_y_min} F6000
        G1 Z{brush_z} F300
        {% for pass in range(wipe_passes) %}
            G1 X{brush_x_min} Y{brush_y_min} F{wipe_speed}
            G1 X{brush_x_max} Y{brush_y_max} F{wipe_speed}
            G1 X{brush_x_min} Y{brush_y_max} F{wipe_speed}
            G1 X{brush_x_max} Y{brush_y_min} F{wipe_speed}
        {% endfor %}
        G1 Z10 F300
        RESPOND MSG="Nozzle wiped"

[gcode_macro SET_HEATER_TEMPERATURE]
rename_existing: SET_HEATER_TEMPERATURE_ORIG
gcode:
    {% set heater = params.HEATER|default("") %}
    {% set target = params.TARGET|default(0)|float %}
    {% if heater in ["YMS-3-PRO", "YMS-4-PRO", "YMS-5-PRO", "YMS-8-PRO", "YMS-9-PRO", "YMS-10-PRO"] and target > 110 %}
        RESPOND TYPE=error MSG="ERROR: { heater } temperature limited to 110C"
        SET_HEATER_TEMPERATURE_ORIG HEATER={heater} TARGET=110
    {% else %}
        SET_HEATER_TEMPERATURE_ORIG HEATER={heater} TARGET={target}
    {% endif %}

[gcode_macro SET_EXTRA_FLUSH]
description: Set purge parameters
gcode:
    {% if 'LENGTH' in params %}
        {% set new_length = params.LENGTH|float %}
        SAVE_VARIABLE VARIABLE=extra_purge_length VALUE={new_length}
        { action_respond_info("Purge length set to %.1fmm" % new_length) }
    {% endif %}
    {% if 'SPEED' in params %}
        {% set new_speed = params.SPEED|float %}
        SAVE_VARIABLE VARIABLE=extra_purge_speed VALUE={new_speed}
        { action_respond_info("Purge speed set to %.1fmm/s" % new_speed) }
    {% endif %}

[gcode_macro EXTRA_FLUSH]
description: Extrude extra filament
gcode:
    {% set svv = printer.save_variables.variables %}
    {% set length = svv.extra_purge_length|default(0)|float %}
    {% set speed = svv.extra_purge_speed|default(5)|float %}
    {% if printer.extruder.can_extrude|lower == 'true' %}
        G92 E0
        G1 E{length} F{speed * 60}
        { action_respond_info("Purge: %.1fmm @ %.1fmm/s" % (length, speed)) }
    {% else %}
        { action_respond_error("ERROR: Temperature too low!") }
    {% endif %}

[gcode_macro INIT_FLUSH_VARS]
description: Initialize purge variables
gcode:
    {% if 'extra_purge_length' not in printer.save_variables.variables %}
        SAVE_VARIABLE VARIABLE=extra_purge_length VALUE=0.0
    {% endif %}
    {% if 'extra_purge_speed' not in printer.save_variables.variables %}
        SAVE_VARIABLE VARIABLE=extra_purge_speed VALUE=5.0
    {% endif %}

[delayed_gcode INIT_YMS]
initial_duration: 0.01
gcode:
    # a boot is never inside a print: whatever a stopped print left in printing_start, T0 takes
    # its idle branch (re-arm every YMS sensor) — a load to the head at power-on fed 2500 mm
    # into nothing on the bench (06/09). PLR's resume re-activates the tool itself.
    SAVE_VARIABLE VARIABLE=printing_start VALUE=False
    M117 INIT YMS
    INIT_FLUSH_VARS
    T0

[gcode_macro _YUMI_CHANGE]
description: Colour change geometry and purge settings, single source for YUMI_TOOL_CHANGE. Values of the slicer block validated on the fleet; to confirm on the bench (Nicolas): popoff_dx, z_clearance, purge Y (current Y)
variable_z_clearance: 3
variable_popoff_dx: 11
variable_prime_len: 20
variable_prime_speed: 200
variable_flush_min: 15
variable_flush_speed: 300
variable_fan_ms: 3000
gcode:
    # settings only

[gcode_macro YUMI_TOOL_CHANGE]
description: BENCH TEST of a colour change on a ChromaX12 (Nicolas, 06/09: in production the change is 100% scripted in the OrcaSlicer G-code, the machine only provides T<n>, YUMI_UNLOAD_CHECK and EXTRA_FLUSH). TOOL=<n> next feeder (0-based, = T<n>), TEMP=<new filament temperature>, FLUSH=<mm to purge, floored at _YUMI_CHANGE.flush_min>. Leaves the part, pop tool at the current Y, tip-shaping unload of the current filament until the head switch releases, T<n> (load to the switch, then to the nozzle), prime, flush + EXTRA_FLUSH, fan burst, pop-off; the slicer's next travel goes back to the part
gcode:
    {% set tool = params.TOOL|int %}
    {% set c = printer["gcode_macro _YUMI_CHANGE"] %}
    {% set pop = printer["gcode_macro _YUMI_POP_TOOL"] %}
    {% set tip = printer["gcode_macro _YUMI_TIP"] %}
    {% set bed = printer["gcode_macro _YUMI_MACHINE"].bed_size|float %}
    {% set z_max = printer.toolhead.axis_maximum.z|float %}
    {% set cur_temp = printer.extruder.target|float %}
    {% set temp = params.TEMP|default(cur_temp)|float %}
    {% set unload_temp = [cur_temp, temp]|max %}
    {% set flush = [params.FLUSH|default(c.flush_min)|float, c.flush_min|float]|max %}
    {% set fan = (printer.fan.speed * 255)|round|int %}
    {% set z = printer.gcode_move.position.z|float %}
    SAVE_GCODE_STATE NAME=yumi_change
    SET_VELOCITY_LIMIT ACCEL=20000 ACCEL_TO_DECEL=10000
    M106 S0
    M104 S{unload_temp}
    # 1. leave the part: the tip sequence's first fast retract, then up and out to the pop tool
    M83
    G1 E-{tip.first_len} F{(tip.first_speed * 60)|int}
    G90
    G1 Z{[z + c.z_clearance, z_max]|min} F1200
    G1 X{bed + pop.approach_dx} F{pop.approach_speed}
    G1 X{bed + pop.pop_dx} F{pop.pop_speed}
    # 2. off the part, at temperature: tip-shaping unload of the current filament, head switch released
    M109 S{unload_temp}
    YUMI_UNLOAD_TIP SKIP_FIRST=1
    # 3. the next feeder: T<n> selects it, loads to the head switch, then head_to_nozzle
    T{tool}
    M104 S{temp}
    # 4. prime and flush into the pop tool, solidify, snap the blob off
    M83
    G1 E{c.prime_len} F{c.prime_speed}
    G1 E{flush} F{c.flush_speed}
    EXTRA_FLUSH
    M106 S255
    G4 P{c.fan_ms}
    G1 X{bed + c.popoff_dx} F{pop.approach_speed}
    M106 S{fan}
    RESTORE_GCODE_STATE NAME=yumi_change

[gcode_macro LOAD_YMS]
description: Load filament into the YMS
gcode:
    RESPOND TYPE=error MSG="macro LOAD_YMS"
    M117 macro LOAD_YMS
    {% if printer.save_variables.variables.printing_start %}
        {% set insert_length = 200|int %}
        {% set speed = 1000|int %}
        G92 E0
        G1 E{insert_length} F{speed}
        G92 E0
        RESPOND MSG="Filament loaded {insert_length}mm at {speed}mm/min"
    {% else %}
        {% set insert_length = 50|int %}
        {% set speed = 1000|int %}
        G92 E0
        G1 E{insert_length} F{speed}
        G92 E0
        RESPOND MSG="Filament loaded {insert_length}mm at {speed}mm/min"
        T0
    {% endif %}
